head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst35300";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst35300.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnSearch_onclick
 * @description btn_fnSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = async function(e){
    try {
        await scwin.fnSearch(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst35300.btn_fnSearch_onclick' }); }
};

/**
 * @method
 * @name btn_goToPageList_onclick
 * @description btn_goToPageList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goToPageList_onclick = async function(e){
    try {
        await scwin.goToPageList('','','',''); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst35300.btn_goToPageList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch
 * @description fn Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/disclosureinfo/regulationsystem.do",
        ref: "dma_fnSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goToPageList
 * @description go To Page List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goToPageList = async function () {
    const sbmOptions = {
        id: "tx_goToPageList",
        method: "post",
        action: "/disclosureinfo/regulationsystem.do",
        ref: "dma_goToPageListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name replaceKeyword
 * @description replace Keyword 처리
 * @param {String} _srcStr _srcStr
 * @param {*} _keyword _keyword
 * @returns {void}
 * @hidden N
 */
scwin.replaceKeyword = function (_srcStr, _keyword) {
    document.write(_srcStr.replace(new RegExp(_keyword, "g"), "<span class='search'>" + _keyword + "</span>"));
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent('dma_fnSearchReq').set('method', "searchRegulationSystemSub");
    $c.util.getComponent('dma_fnSearchReq').set('forward', "regulationsystem_sub1");
    (document.frm || { elements: [] }).target = "iframe";
    (document.frm || { elements: [] }).action = "/disclosureinfo/regulationsystem.do";
    await scwin.tx_fnSearch();
};

/**
 * @method
 * @name goToPageList
 * @description go To Page List 처리
 * @param {*} lawNo lawNo
 * @param {*} lawTitle lawTitle
 * @param {*} dtruleLawNo dtruleLawNo
 * @param {String} lawAmendDd lawAmendDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goToPageList = async function (lawNo, lawTitle, dtruleLawNo, lawAmendDd) {
    $c.util.getComponent('dma_fnSearchReq').set('lawNo', lawNo);
    $c.util.getComponent('dma_fnSearchReq').set('lawTitle', lawTitle);
    $c.util.getComponent('dma_fnSearchReq').set('dtruleLawNo', dtruleLawNo);
    $c.util.getComponent('dma_fnSearchReq').set('lawAmendDd', lawAmendDd);
    $c.util.getComponent('dma_fnSearchReq').set('lawNo', lawNo);
    $c.util.getComponent('dma_fnSearchReq').set('method', "searchRegulationItem");
    $c.util.getComponent('dma_fnSearchReq').set('forward', "regulationsystem_sub2");
    (document.frm || { elements: [] }).target = "iframe";
    (document.frm || { elements: [] }).action = "/disclosureinfo/regulationsystem.do";
    await scwin.tx_goToPageList();
};

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.fnSearch();
        }
    }
};
